//mneguidelines.oecd.org/mining.htm"},Aa=[{id:"solar",name:"Solar modules",hs:"HS 8541.43",indications:["forced-labor","duty-evasion"],history:"Polysilicon, the main input to solar modules, is a UFLPA high-priority sector. In 2023 the U.S. Commerce Department found that certain solar cells and modules completed in Cambodia, Malaysia, Thailand, and Vietnam were circumventing AD/CVD orders on Chinese products. Production then shifted to Indonesia, Laos, and India, which became the subject of new AD/CVD investigations in 2025. Preliminary countervailing duties on Indonesian cells (86–143%) took effect February 26, 2026, with critical circumstances applied to entries about 90 days earlier; final determinations followed in September 2026.",sources:[xc,{label:"Commerce AD/CVD circumvention ruling (2023)"},{label:"Commerce CVD preliminary, Indonesia solar cells (Feb 2026)",href:"https://www.govinfo.gov/content/pkg/FR-2026-02-26/pdf/2026-03896.pdf"}]},{id:"aluminum",name:"Unwrought aluminum",hs:"HS 7601",indications:["forced-labor","duty-evasion"],history:"Aluminum was added as a UFLPA high-priority sector in 2024. Aluminum extrusions are subject to U.S. AD/CVD orders and have been the subject of CBP duty-evasion (EAPA) investigations involving third-country transshipment.",sources:[xc,vS]},{id:"cotton",name:"Cotton T-shirts",hs:"HS 6109.10",indications:["forced-labor"],history:"Cotton is a UFLPA high-priority sector. In January 2021 CBP issued a region-wide Withhold Release Order on cotton and tomato products from Xinjiang, which reaches finished apparel made with that cotton.",sources:[xc]},{id:"seafood",name:"Frozen shrimp",hs:"HS 0306.17",indications:["forced-labor","duty-evasion"],history:"Seafood was added as a UFLPA high-priority sector in 2024. Shrimp from several countries is subject to U.S. AD/CVD orders, and forced labor on fishing vessels has been documented by the ILO and investigative reporting.",sources:[xc,{label:"U.S. AD/CVD orders on shrimp"}]},{id:"honey",name:"Natural honey",hs:"HS 0409",indications:["duty-evasion","illegal-harvest"],history:"U.S. antidumping duties on Chinese honey have applied since 2001. Federal prosecutions around 2013 involved honey transshipped through third countries and mislabeled to evade those duties. Since 2022 a further AD order covers raw honey from Argentina, Brazil, India, and Vietnam.",sources:[{label:"U.S. AD order on honey (2001)"},{label:"DOJ transshipment cases (2013)"},{label:"AD orders on raw honey from Argentina, Brazil, India, Vietnam (87 FR 35501, June 2022)"}]},{id:"gold",name:"Gold, unwrought",hs:"HS 7108",indications:["tbml","conflict"],history:"FATF has identified gold as highly attractive for trade-based money laundering because of its high value-to-weight ratio and cash markets. Gold is also one of the four conflict minerals (3TG) covered by OECD due-diligence guidance.",sources:[{label:"FATF · gold ML/TF risks (2015)",href:"https://www.fatf-gafi.org/"},Uy]},{id:"tin",name:"Tin, unwrought",hs:"HS 8001",indications:["conflict"],history:"Tin is one of the 3TG conflict minerals covered by U.S. Dodd-Frank §1502 reporting and the EU Conflict Minerals Regulation (applied from 2021), both built on OECD due-diligence guidance.",sources:[{label:"EU Conflict Minerals Regulation",href:"https://policy.trade.ec.europa.eu/development-and-sustainability/conflict-minerals-regulation_en"},Uy]},{id:"timber",name:"Tropical sawn timber",hs:"HS 4407.29",indications:["illegal-harvest"],history:"The U.S. Lacey Act prohibits trade in illegally harvested plant products and requires import declarations for many wood products. The EU applies comparable rules to timber placed on its market.",sources:[{label:"U.S. FWS · Lacey Act",href:"https://www.fws.gov/law/lacey-act"}]}],xS=h5.generatedAt,Wn=h5.products,uh=xu.products,bS=xu.generatedAt,SS=xu.riskLabels,jS=xu.flagLabels,RS=m5.generatedAt,p5=m5.products,g5=a=>(p5[a]??[]).filter(l=>l.reviewed!==!1&&l.date).sort((l,c)=>c.date.localeCompare(l.date